def transform(grid):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    seg=None
    for r in range(h):
        for c in range(w-2):
            if g[r][c]!=0 and g[r][c+1]!=0 and g[r][c+2]!=0:
                seg=(r,c); break
        if seg: break
    r0,c0=seg
    cols={g[r0][c0+i]:c0+i for i in range(3)}
    strays=[(r,c,g[r][c]) for r in range(h) for c in range(w)
            if g[r][c]!=0 and not (r==r0 and c0<=c<c0+3)]
    for r,c,v in strays:
        tc=cols[v]
        for cc in range(min(c,tc),max(c,tc)+1): out[r][cc]=v
        for rr in range(0,r+1): out[rr][tc]=v
    mid=cols[g[r0][c0+1]]
    for rr in range(h): out[rr][mid]=g[r0][c0+1]
    return out
